import type { IsoWeekday, RecurrenceFrequency } from "@madeora/domain/tasks";

import type { LabelColor, OccurrenceFilter, SeriesScope, TaskPriority } from "./schema";

/**
 * The HTTP contract of tasks (S18). Every mutation is same-origin JSON, checked again by the database
 * with the person's own session. Ids of new things are generated by the client, so a retried request
 * returns the same record instead of a second one.
 *
 * - `GET /api/v1/tasks?homeId&list&status&when&hideFuture&priority&label&assignee&member&sort&offset`
 *   → `200 { tasks, total }` (at most 50).
 * - `POST /api/v1/tasks` → `201 { revision }`; `PATCH|DELETE /api/v1/tasks/:id`.
 * - `PUT /api/v1/tasks/:id/assignees|list|completion`.
 * - `POST /api/v1/tasks/:id/subtasks`, `PUT /api/v1/tasks/:id/subtasks` (order),
 *   `PATCH|DELETE /api/v1/subtasks/:id`.
 * - `GET|POST /api/v1/tasks/:id/comments`, `PATCH|DELETE /api/v1/task-comments/:id`.
 * - `POST /api/v1/task-lists`, `PUT /api/v1/task-lists` (order), `PATCH|DELETE /api/v1/task-lists/:id`.
 * - `POST /api/v1/task-labels`, `PATCH|DELETE /api/v1/task-labels/:id`.
 * - S19: `POST /api/v1/tasks` with `recurrence` creates a recurring task → `201 { id, taskId }`;
 *   `POST /api/v1/tasks/:id/series` (change following or all occurrences, or preview it),
 *   `POST /api/v1/tasks/:id/series/delete`, `PUT /api/v1/tasks/:id/series/paused`,
 *   `GET /api/v1/tasks/:id/occurrences?filter&offset` (history).
 *
 * `409 conflict` (with the current `revision` when known) means someone changed it since it was read.
 */
export const TASKS_ENDPOINT = "/api/v1/tasks";
export const SUBTASKS_ENDPOINT = "/api/v1/subtasks";
export const TASK_COMMENTS_ENDPOINT = "/api/v1/task-comments";
export const TASK_LISTS_ENDPOINT = "/api/v1/task-lists";
export const TASK_LABELS_ENDPOINT = "/api/v1/task-labels";

export type TaskErrorCode =
  | "forbidden"
  | "unsupported-media-type"
  | "too-large"
  | "unauthenticated"
  | "invalid"
  | "not-found"
  | "not-permitted"
  | "conflict"
  | "duplicate-name"
  | "limit-reached"
  | "list-unavailable"
  | "has-tasks"
  | "has-open-tasks"
  | "id-taken"
  | "has-series"
  | "scope-unavailable"
  | "not-recurring"
  | "schedule-ended"
  | "failed";

export interface TaskErrorResponse {
  readonly error: TaskErrorCode;
  readonly revision?: number;
  /** Tasks still in the way of archiving or deleting a list. */
  readonly count?: number;
  readonly fields?: readonly string[];
}

/** A person as a task shows them: the viewer, a current member (membership id), or nobody known. */
export interface TaskPerson {
  readonly me: boolean;
  readonly member: string | null;
}

export interface TaskListSummary {
  readonly id: string;
  readonly name: string;
  readonly position: number;
  readonly archived: boolean;
  readonly revision: number;
  readonly openTasks: number;
  readonly activeTasks: number;
}

export interface TaskLabel {
  readonly id: string;
  readonly name: string;
  readonly color: LabelColor | null;
  readonly revision: number;
  /** Active tasks of the context that carry it (the impact before removal). */
  readonly taskCount: number;
}

/** One row of a listing: only what the list shows. */
export interface TaskRow {
  readonly id: string;
  readonly listId: string;
  readonly listName: string;
  readonly title: string;
  readonly startDate: string | null;
  readonly dueDate: string | null;
  readonly priority: TaskPriority | null;
  readonly completed: boolean;
  readonly needsReassignment: boolean;
  readonly overdue: boolean;
  readonly upcoming: boolean;
  readonly subtasksDone: number;
  readonly subtasksTotal: number;
  readonly commentCount: number;
  readonly labelIds: readonly string[];
  readonly assigneeIds: readonly string[];
  readonly assignedToMe: boolean;
  /** Whether the viewer may complete or reopen it (the database decides again on every change). */
  readonly canComplete: boolean;
  readonly revision: number;
  /** An occurrence of a recurring series (S19). */
  readonly recurring: boolean;
}

export interface TaskPage {
  readonly tasks: readonly TaskRow[];
  readonly total: number;
}

export interface Subtask {
  readonly id: string;
  readonly title: string;
  readonly completed: boolean;
  readonly revision: number;
}

/** The series an occurrence belongs to (S19): its current part's schedule and template facts. */
export interface TaskSeries {
  readonly revision: number;
  readonly frequency: RecurrenceFrequency;
  readonly interval: number;
  readonly weekdays: readonly IsoWeekday[] | null;
  readonly startsOn: string;
  readonly endsOn: string | null;
  readonly count: number | null;
  readonly startOffset: number | null;
  readonly listId: string | null;
  readonly paused: boolean;
  readonly ended: boolean;
  /** The next open occurrence after today, or the next date still to come; null when ended. */
  readonly nextDate: string | null;
  /** Whether this occurrence belongs to the current part (only then "this and following"). */
  readonly inHead: boolean;
  /** Changed on its own: later series changes leave it as it is. */
  readonly detached: boolean;
  readonly needsReassignment: boolean;
  /** Membership ids of the series' assignees (new occurrences get them). */
  readonly assignees: readonly string[];
  readonly checklistSize: number;
  readonly can: { readonly edit: boolean; readonly assign: boolean; readonly delete: boolean };
}

export interface TaskDetail {
  readonly id: string;
  readonly homeId: string | null;
  readonly list: { readonly id: string; readonly name: string; readonly archived: boolean };
  readonly title: string;
  readonly description: string | null;
  readonly startDate: string | null;
  readonly dueDate: string | null;
  readonly priority: TaskPriority | null;
  readonly revision: number;
  readonly needsReassignment: boolean;
  readonly overdue: boolean;
  readonly upcoming: boolean;
  readonly createdAt: string;
  readonly createdBy: TaskPerson;
  readonly updatedAt: string;
  readonly updatedBy: TaskPerson;
  readonly completedAt: string | null;
  readonly completedBy: TaskPerson | null;
  /** The last reopening, if any (spec: who completed or reopened it, and when). */
  readonly reopenedAt: string | null;
  readonly reopenedBy: TaskPerson | null;
  readonly assignees: readonly string[];
  readonly labels: readonly {
    readonly id: string;
    readonly name: string;
    readonly color: LabelColor | null;
  }[];
  readonly subtasks: readonly Subtask[];
  readonly commentCount: number;
  /** S19: the occurrence's original scheduled date, and its series (null: one-off, or removed). */
  readonly occurrenceDate: string | null;
  readonly series: TaskSeries | null;
  readonly can: {
    readonly edit: boolean;
    readonly complete: boolean;
    readonly assign: boolean;
    readonly delete: boolean;
    readonly comment: boolean;
  };
}

/** What a change to following or all occurrences does (S19), from the dry run or the change. */
export interface SeriesImpact {
  /** The scope applied: "following" turns into "series" when nothing came before this occurrence. */
  readonly scope: SeriesScope;
  readonly updated: number;
  /** Open occurrences changed on their own, left as they are. */
  readonly kept: number;
  /** Upcoming untouched occurrences no longer on the schedule. */
  readonly removed: number;
  /** Completed occurrences in scope, never changed. */
  readonly completed: number;
  readonly selectedRemoved: boolean;
  readonly subtasksCopied: number;
  readonly nextDates: readonly string[];
}

export interface SeriesChangeResponse {
  readonly outcome: "preview" | "saved";
  readonly impact: SeriesImpact;
  readonly revision: number;
  /** This occurrence, or the next open one when the change removed this one; null if none. */
  readonly taskId: string | null;
}

export interface SeriesDeleteImpact {
  readonly scope: SeriesScope;
  readonly removed: number;
  readonly completed: number;
}

export interface SeriesDeleteResponse {
  readonly outcome: "preview" | "deleted";
  readonly impact: SeriesDeleteImpact;
  readonly trashEntryId: string | null;
}

export type OccurrenceStatus = "completed" | "completed_late" | "missed" | "open";

/** One row of a series' history (S19): scheduled date, status, and the actual completer. */
export interface OccurrenceRow {
  readonly id: string;
  readonly occurrenceDate: string;
  readonly dueDate: string | null;
  readonly status: OccurrenceStatus;
  readonly completedAt: string | null;
  readonly completedBy: TaskPerson | null;
  /** The occurrence being viewed. */
  readonly current: boolean;
}

export interface OccurrencePage {
  readonly occurrences: readonly OccurrenceRow[];
  readonly total: number;
  readonly filter: OccurrenceFilter;
}

export interface TaskComment {
  readonly id: string;
  readonly body: string;
  readonly createdAt: string;
  readonly editedAt: string | null;
  readonly revision: number;
  readonly author: TaskPerson;
}

export interface CommentPage {
  readonly comments: readonly TaskComment[];
  readonly total: number;
}

export interface RevisionResponse {
  readonly revision: number;
}

export type CompletionOutcome = "completed" | "reopened" | "already_completed" | "already_open";

export interface CompletionResponse {
  readonly outcome: CompletionOutcome;
  readonly completedAt: string | null;
  /** Who actually completed it (the winner, when someone else was first). */
  readonly completedBy: TaskPerson | null;
}

/** Why a task request failed, in words the interface can explain. */
export type TaskFailure =
  | "signedOut"
  | "invalid"
  | "notFound"
  | "notPermitted"
  | "conflict"
  | "duplicateName"
  | "limitReached"
  | "listUnavailable"
  | "hasTasks"
  | "hasOpenTasks"
  | "hasSeries"
  | "scopeUnavailable"
  | "notRecurring"
  | "scheduleEnded"
  | "network"
  | "failed";

export class TaskRequestError extends Error {
  constructor(
    readonly failure: TaskFailure,
    /** For a conflict, the record's current revision when known; for hasTasks, the count. */
    readonly detail: number | null = null,
  ) {
    super(`Task request failed: ${failure}`);
    this.name = "TaskRequestError";
  }
}

const failures: { readonly [C in TaskErrorCode]?: TaskFailure } = {
  unauthenticated: "signedOut",
  invalid: "invalid",
  "not-found": "notFound",
  "not-permitted": "notPermitted",
  conflict: "conflict",
  "duplicate-name": "duplicateName",
  "limit-reached": "limitReached",
  "list-unavailable": "listUnavailable",
  "has-tasks": "hasTasks",
  "has-open-tasks": "hasOpenTasks",
  "id-taken": "failed",
  "has-series": "hasSeries",
  "scope-unavailable": "scopeUnavailable",
  "not-recurring": "notRecurring",
  "schedule-ended": "scheduleEnded",
};

/** Sends one request; resolves with the JSON answer or rejects with a TaskRequestError. */
export async function sendTaskRequest<T>(method: string, url: string, body?: unknown): Promise<T> {
  let response: Response;
  try {
    response = await fetch(url, {
      method,
      headers: body === undefined ? {} : { "content-type": "application/json" },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
      cache: "no-store",
    });
  } catch {
    throw new TaskRequestError("network");
  }
  const payload: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    const record = (payload && typeof payload === "object" ? payload : {}) as Partial<
      Record<string, unknown>
    >;
    const code = typeof record.error === "string" ? (record.error as TaskErrorCode) : "failed";
    const detail =
      typeof record.revision === "number"
        ? record.revision
        : typeof record.count === "number"
          ? record.count
          : null;
    throw new TaskRequestError(failures[code] ?? "failed", detail);
  }
  return payload as T;
}

/** The query string of a listing request (the same names as the page's search parameters). */
export function taskListingUrl(homeId: string | null, params: URLSearchParams): string {
  const query = new URLSearchParams(params);
  query.delete("homeId");
  if (homeId) query.set("homeId", homeId);
  return `${TASKS_ENDPOINT}?${query.toString()}`;
}
